const promoteReplacementPrimaryCalendarConnection = `-- name: PromoteReplacementPrimaryCalendarConnection :exec
UPDATE calendar_connections
SET is_primary = TRUE,
    updated_at = CURRENT_TIMESTAMP
WHERE connection_id = (
    SELECT candidate.connection_id
    FROM calendar_connections candidate
    WHERE candidate.user_id = $1
      AND candidate.revoked_at IS NULL
      AND candidate.cleanup_pending_at IS NULL
      AND (
          (candidate.provider = 'google'
              AND CAST($2 AS text) = ANY(candidate.scopes)
              AND CAST($3 AS text) = ANY(candidate.scopes))
          OR (candidate.provider = 'microsoft'
              AND CAST($4 AS text) = ANY(candidate.scopes))
      )
    ORDER BY candidate.created_at, candidate.connection_id
    LIMIT 1
)
`

type PromoteReplacementPrimaryCalendarConnectionParams struct {
	UserID              uuid.UUID
	GoogleReadScope     string
	GoogleOwnedScope    string
	MicrosoftWriteScope string
}

