const upsertCalendarConnection = `-- name: UpsertCalendarConnection :one
INSERT INTO calendar_connections (
    workspace_id,
    user_id,
    credential_generation,
    provider_account_id,
    provider,
    is_primary,
    connected_email,
    timezone,
    token_payload,
    scopes,
    sync_status,
    sync_error,
    revoked_at,
    updated_at
) VALUES (
    $1,
    $2,
    $3,
    $4,
    $5,
    (
        CAST($6 AS boolean)
        AND NOT EXISTS (
            SELECT 1
            FROM calendar_connections primary_connection
            WHERE primary_connection.user_id = $2
              AND primary_connection.is_primary = TRUE
        )
    ),
    $7,
    $8,
    $9,
    CAST($10 AS text[]),
    'connected',
    NULL,
    NULL,
    CURRENT_TIMESTAMP
)
ON CONFLICT (user_id, provider)
WHERE revoked_at IS NULL
DO UPDATE SET
    credential_generation = EXCLUDED.credential_generation,
    is_primary = calendar_connections.is_primary OR EXCLUDED.is_primary,
    provider_account_id = EXCLUDED.provider_account_id,
    connected_email = EXCLUDED.connected_email,
    timezone = EXCLUDED.timezone,
    token_payload = EXCLUDED.token_payload,
    scopes = EXCLUDED.scopes,
    sync_status = 'connected',
    sync_error = NULL,
    sync_token = NULL,
    notification_channel_id = NULL,
    notification_resource_id = NULL,
    notification_expires_at = NULL,
    last_synced_at = CASE
        WHEN calendar_connections.provider_account_id <> ''
          AND calendar_connections.provider_account_id = EXCLUDED.provider_account_id
            THEN calendar_connections.last_synced_at
        ELSE NULL
    END,
    updated_at = CURRENT_TIMESTAMP
RETURNING calendar_connections.connection_id, calendar_connections.workspace_id, calendar_connections.user_id, calendar_connections.provider, calendar_connections.connected_email, calendar_connections.timezone, calendar_connections.token_payload, calendar_connections.scopes, calendar_connections.sync_status, calendar_connections.sync_error, calendar_connections.last_synced_at, calendar_connections.revoked_at, calendar_connections.created_at, calendar_connections.updated_at, calendar_connections.provider_account_id, calendar_connections.credential_generation, calendar_connections.sync_token, calendar_connections.notification_channel_id, calendar_connections.notification_resource_id, calendar_connections.notification_expires_at, calendar_connections.cleanup_pending_at, calendar_connections.is_primary
`

